package com.google.javascript.jscomp;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class DeadAssignmentsEliminationAI76Test {

  @Test
  public void testDeadAssignmentSimple() {
    Compiler compiler = new Compiler();
    CompilerOptions options = new CompilerOptions();
    options.deadAssignmentElimination = true;
    compiler.initOptions(options);

    JSSourceFile externs = JSSourceFile.fromCode("externs.js", "");
    JSSourceFile input = JSSourceFile.fromCode("input.js", "function f() { var x = 1; x = 2; return x; }");

    compiler.compile(externs, new JSSourceFile[] { input }, new JSSourceFile[0]);
    String result = compiler.toSource();
    assertEquals("function f(){var x;x=2;return x}", result);
  }

  @Test
  public void testNoDeadAssignmentWhenRead() {
    Compiler compiler = new Compiler();
    CompilerOptions options = new CompilerOptions();
    options.deadAssignmentElimination = true;
    compiler.initOptions(options);

    JSSourceFile externs = JSSourceFile.fromCode("externs.js", "");
    JSSourceFile input = JSSourceFile.fromCode("input.js", "function f() { var x = 1; return x; }");

    compiler.compile(externs, new JSSourceFile[] { input }, new JSSourceFile[0]);
    String result = compiler.toSource();
    assertEquals("function f(){var x=1;return x}", result);
  }

  @Test
  public void testGlobalScopeIgnored() {
    Compiler compiler = new Compiler();
    CompilerOptions options = new CompilerOptions();
    options.deadAssignmentElimination = true;
    compiler.initOptions(options);

    JSSourceFile externs = JSSourceFile.fromCode("externs.js", "");
    JSSourceFile input = JSSourceFile.fromCode("input.js", "var x = 1; x = 2;");

    compiler.compile(externs, new JSSourceFile[] { input }, new JSSourceFile[0]);
    String result = compiler.toSource();
    assertEquals("var x=1;x=2", result);
  }
}
